bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec "$name" node -e 'fetch("http://127.0.0.1:8766/health").then(r=>process.exit(r.status===200?0:1)).catch(()=>process.exit(1))' || exit 82
echo STK_SHOP_INTERNAL_HTTP_READY=PASS
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1});
try{
 const q=await pool.query("SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='videobot_sticker_orders' AND column_name='invoice_url') AS ok");
 if(q.rows[0]?.ok!==true)process.exitCode=83;else console.log('STK_SHOP_SQL_016=PASS');
}finally{await pool.end();}
NODE
